script:
card({ name: "Countdown", icon: 'hourglass' });
const words = {
  until: "Until {p0}",
  days: "{p0} days",
  done: "It's time!",
  when: "",
};

// When to count down to, in ms since 1970 (UTC).
const target = 0;
// Draw the card again every second. This never sends anything.
every(1000);

function view(state, me, now) {
  const left = Math.max(0, target - now);
  if (left === 0) return text(words.done, { size: 'large', bold: true, align: 'center', tone: 'success' });
  const s = Math.floor(left / 1000);
  const pad = n => String(n).padStart(2, '0');
  const clock = pad(Math.floor(s % 86400 / 3600)) + ':' + pad(Math.floor(s % 3600 / 60)) + ':' + pad(s % 60);
  return column([
    text(words.days.replace('{p0}', Math.floor(s / 86400)), { size: 'large', bold: true, align: 'center', tone: 'accent' }),
    text(clock, { size: 'huge', align: 'center' }),
    text(words.until.replace('{p0}', words.when), { tone: 'muted', align: 'center' }),
  ]);
}
